import json
from typing import Any

def parse_tool_call(text: str) -> dict[str, Any]:
    """Parse exactly {tool, arguments}, preserving duplicate-key detection."""
    if not isinstance(text, str):
        raise TypeError("input must be a JSON string")
    def pairs(items: list[tuple[str, Any]]) -> dict[str, Any]:
        result: dict[str, Any] = {}
        for key, value in items:
            if key in result:
                raise ValueError(f"duplicate field: {key}")
            result[key] = value
        return result
    try:
        value = json.loads(text, object_pairs_hook=pairs)
    except (json.JSONDecodeError, ValueError) as exc:
        raise ValueError("invalid JSON or duplicate field") from exc
    if not isinstance(value, dict): raise ValueError("top level must be an object")
    if set(value) != {"tool", "arguments"}:
        raise ValueError("required fields are tool and arguments; no unknown fields")
